import java.util.Date;

public class Solution {
    static final class Period {
        private final Date start;
        private final Date end;

        public Period(Date start, Date end) {
            this.start = new Date(start.getTime());
            this.end = new Date(end.getTime());
            if (this.start.compareTo(this.end) > 0) {
                throw new IllegalArgumentException("Start date must precede end date");
            }
        }

        public Date getStart() {
            return new Date(start.getTime());
        }

        public Date getEnd() {
            return new Date(end.getTime());
        }
    }

    public static void main(String[] args) {
        Date start = new Date(1700000000000L);
        Date end = new Date(1700050000000L);
        Period period = new Period(start, end);

        // External mutation attempt via input reference
        start.setTime(0L);
        // External mutation attempt via getter reference
        period.getEnd().setTime(0L);

        System.out.println("Period start protected: " + (period.getStart().getTime() == 1700000000000L));
        System.out.println("Period end protected:   " + (period.getEnd().getTime() == 1700050000000L));
    }
}

