public class Solution {
    static class BankAccount {
        private double balance;
        private final double overdraftLimit;

        public BankAccount(double initialBalance, double overdraftLimit) {
            this.balance = initialBalance;
            this.overdraftLimit = Math.max(0, overdraftLimit);
        }

        public boolean withdraw(double amount) {
            if (amount <= 0 || amount > (balance + overdraftLimit)) {
                return false; // Transaction rejected: exceeds combined limit
            }
            balance -= amount;
            return true;
        }

        public double getBalance() { return balance; }
    }

    public static void main(String[] args) {
        BankAccount acc = new BankAccount(100.0, 200.0); // Can spend up to $300
        boolean tx1 = acc.withdraw(250.0); // Valid: uses $150 overdraft
        boolean tx2 = acc.withdraw(100.0); // Rejected: exceeds remaining limit

        System.out.println("Transaction 1 ($250) approved: " + tx1);
        System.out.println("Transaction 2 ($100) approved: " + tx2);
        System.out.println("Current Balance: $" + acc.getBalance());
    }
}

