public class Solution {
    static class Range {
        private int start;
        private int end;

        public Range(int start, int end) {
            if (start > end) throw new IllegalArgumentException("start must be <= end");
            this.start = start;
            this.end = end;
        }

        public int getStart() { return start; }
        public int getEnd() { return end; }

        public void setStart(int start) {
            if (start > this.end) throw new IllegalArgumentException("start cannot exceed end (" + this.end + ")");
            this.start = start;
        }

        public void setEnd(int end) {
            if (end < this.start) throw new IllegalArgumentException("end cannot be less than start (" + this.start + ")");
            this.end = end;
        }
    }

    public static void main(String[] args) {
        Range r = new Range(5, 15);
        r.setStart(8);
        try {
            r.setStart(20); // Illegal: 20 > 15
        } catch (IllegalArgumentException e) {
            System.out.println("Caught error: " + e.getMessage());
        }
        System.out.println("Valid Range: [" + r.getStart() + " to " + r.getEnd() + "]");
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

public class Solution {
    static class ObservableCounter {
        private int value = 0;
        private final List<Consumer<Integer>> listeners = new ArrayList<>();

        public void addListener(Consumer<Integer> listener) {
            if (listener != null) listeners.add(listener);
        }

        public void increment() {
            this.value++;
            notifyListeners();
        }

        private void notifyListeners() {
            for (Consumer<Integer> listener : listeners) {
                listener.accept(this.value);
            }
        }

        public int getValue() { return value; }
    }

    public static void main(String[] args) {
        ObservableCounter counter = new ObservableCounter();
        counter.addListener(val -> System.out.println("Listener notified: Count changed to " + val));
        counter.increment();
        counter.increment();
    }
}

