public class Solution {
    static final class Money {
        private final long cents;
        private final String currency;

        public Money(long cents, String currency) {
            if (currency == null || currency.isBlank()) throw new IllegalArgumentException("Invalid currency");
            this.cents = cents;
            this.currency = currency;
        }

        public Money plus(Money other) {
            if (!this.currency.equals(other.currency)) {
                throw new IllegalArgumentException("Currency mismatch: " + this.currency + " vs " + other.currency);
            }
            return new Money(Math.addExact(this.cents, other.cents), this.currency);
        }

        @Override
        public String toString() {
            return String.format("%s %.2f", currency, cents / 100.0);
        }
    }

    public static void main(String[] args) {
        Money m1 = new Money(2500, "USD"); // $25.00
        Money m2 = new Money(1450, "USD"); // $14.50
        Money total = m1.plus(m2);
        System.out.println("Total: " + total);
    }
}

public class Solution {
    enum State { PENDING, PAID, SHIPPED, DELIVERED, CANCELLED }

    static class OrderWorkflow {
        private State currentState = State.PENDING;

        public State getState() { return currentState; }

        public void pay() {
            if (currentState != State.PENDING) {
                throw new IllegalStateException("Cannot pay for order in state: " + currentState);
            }
            currentState = State.PAID;
        }

        public void ship() {
            if (currentState != State.PAID) {
                throw new IllegalStateException("Cannot ship order in state: " + currentState);
            }
            currentState = State.SHIPPED;
        }
    }

    public static void main(String[] args) {
        OrderWorkflow order = new OrderWorkflow();
        order.pay();
        System.out.println("Order transitioned to: " + order.getState());
        try {
            order.pay(); // Invalid: already paid
        } catch (IllegalStateException e) {
            System.out.println("Caught error: " + e.getMessage());
        }
    }
}

import java.util.Arrays;

public class Solution {
    static class SecureVault implements AutoCloseable {
        private byte[] secretKey;
        private boolean destroyed = false;

        public SecureVault(byte[] key) {
            this.secretKey = Arrays.copyOf(key, key.length);
        }

        public boolean isDestroyed() { return destroyed; }

        @Override
        public void close() {
            if (!destroyed && secretKey != null) {
                Arrays.fill(secretKey, (byte) 0); // Scrub sensitive memory
                destroyed = true;
            }
        }
    }

    public static void main(String[] args) {
        byte[] key = {10, 20, 30, 40};
        SecureVault vault = new SecureVault(key);
        System.out.println("Vault active, destroyed: " + vault.isDestroyed());
        vault.close();
        System.out.println("Vault closed, destroyed: " + vault.isDestroyed());
    }
}

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    static class TargetModel {
        private final List<String> tags = new ArrayList<>();
        public TargetModel() { tags.add("java"); }
        // Leaks reference directly
        public List<String> getTags() { return tags; }
    }

    public static boolean auditReferenceLeak(Object instance) throws Exception {
        Class<?> clazz = instance.getClass();
        for (Method m : clazz.getDeclaredMethods()) {
            if (m.getName().startsWith("get") && m.getParameterCount() == 0) {
                Object returned = m.invoke(instance);
                for (Field f : clazz.getDeclaredFields()) {
                    f.setAccessible(true);
                    Object actual = f.get(instance);
                    if (returned != null && returned == actual) {
                        return true; // Leak detected: exact same reference returned
                    }
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        TargetModel model = new TargetModel();
        boolean leaked = auditReferenceLeak(model);
        System.out.println("Auditor detected encapsulation leak: " + leaked);
    }
}

import java.util.concurrent.atomic.AtomicLong;

public class Solution {
    static class MetricsCollector {
        private final AtomicLong successCount = new AtomicLong(0);
        private final AtomicLong failureCount = new AtomicLong(0);

        public void recordSuccess() {
            successCount.incrementAndGet();
        }

        public void recordFailure() {
            failureCount.incrementAndGet();
        }

        public long getSuccessCount() { return successCount.get(); }
        public long getFailureCount() { return failureCount.get(); }
    }

    public static void main(String[] args) throws InterruptedException {
        MetricsCollector collector = new MetricsCollector();
        Thread t1 = new Thread(() -> { for (int i = 0; i < 500; i++) collector.recordSuccess(); });
        Thread t2 = new Thread(() -> { for (int i = 0; i < 500; i++) collector.recordSuccess(); });
        t1.start(); t2.start();
        t1.join(); t2.join();

        System.out.println("Total Successful Invocations: " + collector.getSuccessCount());
    }
}
